            for a, b in zip(xs, xs[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
            # If a repeated marked column lies just to the right of this
            # horizontal trace, join the trace to that perpendicular line.
            right_columns = [c for c in range(max(xs) + 1, w)
