                end = min(right_columns)
                for c in range(max(xs) + 1, end + 1):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # Complete gaps between consecutive marks in sufficiently supported
    # vertical lines. All endpoint decisions use the original input grid.
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        if len(ys) >= 3:
            for a, b in zip(ys, ys[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
