    out = [row[:] for row in grid]

    # Complete established horizontal marked runs between their endpoints.
    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == marker]
        if len(xs) >= 3:
            for c in range(min(xs), max(xs) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Complete vertical runs with three or more marks; a two-point vertical
    # pair is completed only when the endpoints have one missing cell between.
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        if len(ys) >= 3 or (len(ys) == 2 and ys[1] - ys[0] == 2):
            for r in range(min(ys), max(ys) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Where a horizontal run directly meets a supported vertical line, fill
    # the connecting cell to the first such line on its right.
    supported_cols = [c for c in range(w)
                      if sum(grid[r][c] == marker for r in range(h)) >= 3]
    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == marker]
        if len(xs) >= 3:
            right = [c for c in supported_cols if c > max(xs)]
            if right:
                end = min(right)
                for c in range(max(xs) + 1, end + 1):
                    if grid[r][c] == background:
                        out[r][c] = 2
    return out

